def slugify(text):
    return "-".join(text.lower().split())


def test_lowercases():
    assert slugify("Hello") == "hello"


def test_spaces_become_dashes():
    assert slugify("a b c") == "a-b-c"


def test_empty_string():
    assert slugify("") == ""

