import logging

log = logging.getLogger("orders")


def parse_quantities(rows):
    good = []
    for row in rows:
        try:
            good.append(int(row))
        except ValueError:
            log.warning("bad row: %r", row)
    log.info("parsed %d rows", len(good))
    return good

