lessons.solution:
import re
import tomllib


def summarize(text):
    project = tomllib.loads(text).get("project")
    if not project:
        raise ValueError("missing [project]")
    for key in ("name", "version"):
        if key not in project:
            raise ValueError(f"missing {key}")
    names = [
        re.match(r"[A-Za-z0-9._-]+", dep).group()
        for dep in project.get("dependencies", [])
    ]
    return {
        "name": project["name"],
        "version": project["version"],
        "dependencies": names,
        "scripts": project.get("scripts", {}),
    }

checks.code:
for text in ['[build-system]\nrequires = []\n', '[project]\nversion = "1"\n', '[project]\nname = "a"\n']:
    raised = False
    try:
        summarize(text)
    except ValueError:
        raised = True
    assert raised, f"{text!r} should raise ValueError"
